perl -e '
use strict; use warnings;
my $repo = "/bench/repo";
my $internal = "$repo/internal";

# Parse declarations in internal non-test go files
my %decls; # sym -> [paths]
opendir(my $dh, $internal) or die;
# walk recursively
sub walk {
  my ($dir) = @_;
  opendir(my $d, $dir) or return;
  for my $f (readdir $d) {
    next if $f =~ /^\./;
    my $p = "$dir/$f";
    if (-d $p) { walk($p); next; }
    next unless $f =~ /\.go$/ && $f !~ /_test\.go$/;
    my $rel = $p; $rel =~ s|^\Q$repo/||;
    open my $fh, "<", $p or next;
    local $/; my $c = <$fh>; close $fh;
    while ($c =~ /^func\s+([A-Z]\w*)\s*\(/mg) {
      push @{ $decls{$1} }, $rel;
    }
    while ($c =~ /^func\s+\([^)]*\)\s+([A-Z]\w*)\s*\(/mg) {
      push @{ $decls{$1} }, $rel;
    }
  }
  closedir $d;
}
walk($internal);

# grep all references
my @results;
for my $sym (sort keys %decls) {
  my @lines = qx(grep -r --include=*.go -n \Q$sym\E $repo 2>/dev/null);
  my %caller_files;
  my $calls = 0;
  for my $line (@lines) {
    chomp $line;
    my ($file, $rest) = split /:/, $line, 2;
    next if $file =~ /_test\.go$/;
    next if $file =~ m|/internal/testutil/|;
    next if $rest =~ /^func\s+(\([^)]*\)\s+)?\Q$sym\E\s*\(/;
    next if $rest =~ /^func\s+\([^)]*\)\s+\Q$sym\E\s*\(/;
    next if $rest =~ /\btype\s+\Q$sym\E\b/;
    my $n = () = $rest =~ /\b\Q$sym\E\b/g;
    next unless $n;
    $calls += $n;
    (my $f = $file) =~ s|^\Q$repo/||;
    $caller_files{$f} = 1;
  }
  next unless $calls > 0;
  push @results, [$calls, scalar(keys %caller_files), $sym, $decls{$sym}[0]];
}
@results = sort { $b->[0] <=> $a->[0] || $b->[1] <=> $a->[1] } @results;
for my $r (@results[0..49]) {
  printf "%d\t%d\t%s\t%s\n", @$r;
}
'

