perl -e '
use strict; use warnings;
my $repo = "/bench/repo";
my @decls;

sub walk {
  my ($dir)=@_;
  opendir(my $d,$dir) or return;
  for my $f (readdir $d) {
    next if $f=~/^\./;
    my $p="$dir/$f";
    if (-d $p) { walk($p); next; }
    next unless $f=~/\.go$/ && $f!~/_test\.go$/;
    my $rel=$p; $rel=~s|^\Q$repo/||;
    open my $fh,"<",$p or next;
    local $/; my $c=<$fh>; close $fh;
    while ($c=~/^func\s+(?:\((\w+)\s+\*?(\w+)\)\s+)?(\w+)\s*\(/mg) {
      my ($recv,$rtype,$name)=($1,$2,$3);
      my $id = $recv ? "$rtype.$name" : $name;
      push @decls, {id=>$id, name=>$name, recv=>$rtype, path=>$rel, line=>0};
    }
  }
  closedir $d;
}
walk("$repo/internal");

my @results;
for my $d (@decls) {
  my $name = $d->{name};
  my @lines = qx(grep -r --include=*.go -n \Q$name\E\( $repo 2>/dev/null);
  my $n=0; my %files;
  for my $line (@lines) {
    chomp $line;
    my ($file,$lineno,$rest)=split /:/,$line,3;
    next if $file=~/_test\.go$/;
    next if $rest=~/^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/;
    next if $rest=~/^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
    # for methods, require dot call unless same-package bare call unlikely
    if ($d->{recv}) {
      next unless $rest=~/\.\Q$name\E\s*\(/;
    }
    $n++;
    (my $f=$file)=~s|^\Q$repo/||; $files{$f}=1;
  }
  push @results, [$n, scalar keys %files, $d->{id}, $d->{path}] if $n>0;
}
@results = sort { $b->[0] <=> $a->[0] || $b->[1] <=> $a->[1] } @results;
for (@results[0..29]) { printf "%d\t%d\t%s\t%s\n", @$_; }
'

