sub is_data_layer {
  my ($file) = @_;
  $file =~ s|^\Q$repo/||;
  return 1 if $file =~ m|^store(/|$)|;
  return 0;
}

sub pkg_dir {
  my ($file) = @_;
  $file =~ s|^\Q$repo/||;
  $file =~ s|/[^/]+$||;
  return $file;
}

for my $type (@entities) {
  my @lines = qx{grep -r --include="*.go" -n "store\\.$type\\b" $repo 2>/dev/null};
  my %pkgs;
  for my $line (@lines) {
    chomp $line;
    my ($file) = split /:/, $line, 2;
    next if $file =~ /_test\.go$/;
    next if is_data_layer($file);
    $pkgs{pkg_dir($file)} = 1;
  }
  printf "%2d %s\n", scalar(keys %pkgs), $type;
  for my $p (sort keys %pkgs) { print "    $p\n"; }
  print "\n";
}
